probe_extension:
static void cassette_on(unsigned milliseconds) {
    uint32_t args[]={0,1,milliseconds};command_inventure_feeder(args);
}
static void cassette_timer_poll(void) {
    if(feeder_running[0] && (int32_t)(mock_now-feeder_until[0])>=0) {
        sched_del_timer(&feeder_timer[0]);
        assert(feeder_end(&feeder_timer[0])==SF_DONE);
    }
}
int main(void) {
    unsigned rates[]={960,1280,1536};
    for(unsigned k=0;k<3;k++) {
        unsigned rate=rates[k],steps=rate/2;
        control_reset(0);output(1,6,64,1500,250,9001);
        assert(co[6].duty==64);
        motion(1,0,0,0,0,steps,rate,10,750,0,0,0,9002);
        assert(cm.active);
        cassette_on((steps*1000+1535)/1536);
        assert(feeder_running[0] && cm.active && co[6].duty==64);
        assert(outputs[GPIO('A',8)]==1 && !(cm.direction&BIT(3)));
        while(cm.active){motion_tick();cassette_timer_poll();control_guard(mock_now);cooling_update();}
        cassette_timer_poll();
        assert(!feeder_running[0]);assert(cm.phase==CM_DONE && cm.sent[3]==steps);
        assert(cm.sent[0]==0 && cm.sent[1]==0 && cm.sent[2]==0 && co[6].duty==64);
        output(1,6,65,1500,250,9003);assert(co[6].token==9003 && co[6].duty==65);
        advance(1500);assert(co[6].duty==0);
    }
    for(unsigned cause=0;cause<4;cause++) {
        control_reset(0);output(1,6,64,1500,250,9001);
        motion(1,0,0,0,0,768,1536,10,750,0,0,0,9002);cassette_on(500);
        assert(feeder_running[0] && cm.active && co[6].duty);
        if(cause==0)control_command(2,0);
        if(cause==1){heartbeat_live=0;control_guard(mock_now);}
        if(cause==2){GPIOD->IDR|=BIT(11);control_guard(mock_now);}
        if(cause==3){
            inventure_adc_observe(ADC1,10,1800);control_guard(mock_now);
            // SERVICE independently cuts the heater at its hardware limit.
            // The host's next checked sample issues the common STOP for motion.
            assert(!co[6].duty && co[6].reason==4 && cm.active && feeder_running[0]);
            control_command(2,0);
        }
        assert(!feeder_running[0] && !cm.active && !co[6].duty);
        assert(outputs[GPIO('C',5)]==0);
    }
    puts("PASS actual R5: simultaneous T0 heat, E DIR0 and left cassette DIR1 at 960/1280/1536 Hz; feeder expiry; heater renewal/expiry; STOP/heartbeat/cable stop all three; independent overheat cuts heat, host STOP stops motion");
    return 0;
}
